package web

const indexHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>触导标识核准台</title><link rel="stylesheet" href="/static/app.css"></head><body><main><header><p class="eyebrow">无障碍版样 · 本地确定性核准</p><h1>触导标识核准台</h1><p>从唯一建档、实测修订、规则校核到冻结授权的单一工作流</p></header>
<nav><button id="refreshCases" type="button">刷新发布案</button><select id="caseList"><option value="">选择已有发布案</option></select><span id="caseInfo">尚未选择发布案</span></nav>
<section><h2>一、建档预检</h2><form id="create"><label>建筑区域<input name="buildingZone" required maxlength="120"></label><label>安装位置<input name="installationLocation" required maxlength="120"></label><label>目标人群<input name="audienceProfile" required maxlength="120"></label><label>适用标准<select name="standardVersion" id="standardVersion"></select></label><label>设计人员<input name="designerID" required maxlength="64"></label><label>检测人员<input name="measurerID" required maxlength="64"></label><label>建档幂等键<input name="idempotencyKey" id="createKey" required maxlength="128"></label><div class="actions"><button id="preflightCreate" type="button">运行预检</button><button>确认建档</button></div></form><div id="createCheck" class="result muted">等待预检</div></section>
<section><h2>二、修订差异与实测证据</h2><form id="revision"><label>盲文编码<input name="braille_cells" required></label><label>点距 (mm)<input name="dot_spacing_mm" type="number" step="0.001" required></label><label>点高 (mm)<input name="dot_height_mm" type="number" step="0.001" required></label><label>凸字高度 (mm)<input name="raised_text_height_mm" type="number" step="0.001" required></label><label>倒角半径 (mm)<input name="bevel_radius_mm" type="number" step="0.001" required></label><label>材质<input name="material_code" required></label><label>对比度<input name="contrast_ratio" type="number" step="0.001" required></label><label>安装高度 (mm)<input name="mounting_height_mm" type="number" step="0.001" required></label><label>提交人员<input name="submitted_by" required></label><fieldset><legend>六类证据摘要与说明</legend><div id="evidenceRows"></div></fieldset><fieldset><legend>整改目标（有 OPEN BLOCK 时必选）</legend><div id="remediationTargets" class="muted">当前没有可选阻断发现</div></fieldset><fieldset><legend>退回项回应</legend><div id="responseTargets" class="muted">当前没有待回应项</div></fieldset><div class="actions"><button id="previewRevision" type="button">预览差异与覆盖</button><button>确认不可变修订</button></div></form><div id="revisionPreview" class="result muted">等待差异预览</div></section>
<section><h2>三、确定性校核与迁移对比</h2><div class="actions"><button id="check" type="button">运行合规校核</button><button id="history" type="button">查看运行历史</button><button id="compare" type="button">对比相邻修订</button></div><div id="checkResult" class="result muted">尚未校核</div></section>
<section><h2>四、整改复核</h2><form id="returnReview"><label>复核人员<input name="reviewerID" value="independent-reviewer" required></label><label>原因分类<select name="category"><option value="EVIDENCE_INSUFFICIENT">证据不足</option><option value="DESCRIPTION_UNCLEAR">说明不清</option><option value="MEASUREMENT_QUESTION">实测疑问</option><option value="OTHER">其他</option></select></label><label>责任角色<select name="responsible_role"><option value="MEASURER">检测人员</option><option value="DESIGNER">设计人员</option></select></label><label>具体说明<textarea name="description" required></textarea></label><button>结构化退回</button></form><div class="actions"><button id="approve" type="button">确认已回应项并批准</button></div><div id="reviewResult" class="result muted">尚无复核决定</div></section>
<section><h2>五、冻结清单与制作授权</h2><div class="actions"><button id="previewFreeze" type="button">生成只读预览</button><button id="freeze" type="button" disabled>确认摘要并冻结</button><button id="issue" type="button">签发凭据</button></div><div id="freezeResult" class="result muted">尚未生成冻结预览</div></section>
<section><h2>六、凭据本地核验</h2><label>完整凭据 JSON<textarea id="credentialJSON" rows="8"></textarea></label><div class="actions"><button id="useIssued" type="button">选择当前已签发凭据</button><button id="verify" type="button">核验并记录</button><button id="verifyHistory" type="button">最近核验记录</button></div><div id="verifyOut" class="result muted">等待核验</div></section>
<pre id="output" aria-live="polite"></pre></main><script src="/static/app.js"></script></body></html>`

const cssText = `:root{color-scheme:light;--ink:#17221f;--jade:#176b5b;--line:#ccd8d4;--paper:#f2f5f1;--warn:#a24d13}*{box-sizing:border-box}body{font-family:system-ui,"Noto Sans SC",sans-serif;background:var(--paper);color:var(--ink);margin:0}main{max-width:1120px;margin:auto;padding:28px}header{border-left:7px solid var(--jade);padding-left:20px;margin-bottom:20px}.eyebrow{color:var(--jade);font-weight:700;letter-spacing:.08em}nav,section{background:#fff;border:1px solid var(--line);border-radius:10px;padding:18px;margin:14px 0}nav{display:flex;gap:10px;align-items:center;position:sticky;top:0;z-index:2}h1{margin:.1em 0}h2{font-size:1.15rem}form{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:12px}label{display:grid;gap:5px;font-weight:650}input,select,textarea,button{padding:10px;border:1px solid #9aaca6;border-radius:5px;font:inherit}textarea{resize:vertical}button{background:var(--jade);border-color:var(--jade);color:#fff;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}fieldset{grid-column:1/-1;border:1px solid var(--line);display:grid;gap:8px}.evidence-row,.target-row{display:grid;grid-template-columns:150px 1fr 1.4fr;gap:8px;align-items:center}.actions{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px}.result{border-left:4px solid var(--jade);padding:10px;margin-top:12px;white-space:pre-wrap;overflow:auto}.muted{color:#63736e}.bad{border-left-color:var(--warn);color:#702e09}pre{white-space:pre-wrap;background:#12201d;color:#dff4ed;padding:14px;border-radius:8px;max-height:420px;overflow:auto}@media(max-width:680px){main{padding:12px}.evidence-row,.target-row{grid-template-columns:1fr}nav{position:static;align-items:stretch;flex-direction:column}}`

const jsText = `let current=null,freezePreview=null,revisionPreview=null;const output=document.querySelector('#output');const evidenceKinds=[['dot_spacing','点距'],['dot_height','点高'],['raised_text','凸字'],['bevel','倒角'],['contrast','对比度'],['mounting_height','安装高度']];function show(el,v,bad=false){el.textContent=typeof v==='string'?v:JSON.stringify(v,null,2);el.classList.toggle('bad',bad);el.classList.remove('muted')}async function req(url,opt={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...opt});const text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data={message:text}}if(!r.ok){const e=new Error(data?.message||'请求失败');e.data=data;throw e}return data}function err(el,e){show(el,e.data||e.message,true)}function render(){document.querySelector('#caseInfo').textContent=current?('案号 '+current.id+' · '+current.status+' · 聚合版本 '+current.version):'尚未选择发布案';renderTargets()}function renderTargets(){const rev=current?.revisions?.at(-1);const blocks=(current?.findings||[]).filter(x=>x.revision_id===rev?.id&&x.severity==='BLOCK'&&x.status==='OPEN');document.querySelector('#remediationTargets').innerHTML=blocks.length?blocks.map(x=>'<label class="target-row"><input type="checkbox" data-finding="'+x.id+'"><span>'+x.rule_id+'</span><input data-explain="'+x.id+'" placeholder="整改说明与计划字段（逗号分隔）"></label>').join(''):'当前没有可选阻断发现';const returns=(current?.return_items||[]).filter(x=>x.status!=='CLOSED');document.querySelector('#responseTargets').innerHTML=returns.length?returns.map(x=>'<label class="target-row"><input type="checkbox" data-return="'+x.id+'"><span>'+x.category+' · '+x.description+'</span><input data-response="'+x.id+'" placeholder="回应 | 新证据摘要"></label>').join(''):'当前没有待回应项'}async function loadCases(){const list=await req('/api/cases');const select=document.querySelector('#caseList');select.innerHTML='<option value="">选择已有发布案</option>'+list.map(c=>'<option value="'+c.id+'">'+c.id+' · '+c.status+'</option>').join('')}async function loadCase(id){current=await req('/api/cases/'+id);render();show(output,current)}
async function loadStandards(){const versions=await req('/api/standards');document.querySelector('#standardVersion').innerHTML=versions.filter(x=>x.enabled).map(x=>'<option value="'+x.id+'">'+x.label+'</option>').join('')}document.querySelector('#evidenceRows').innerHTML=evidenceKinds.map(([k,l])=>'<div class="evidence-row" data-kind="'+k+'"><strong>'+l+'</strong><input class="digest" placeholder="SHA-256 十六进制摘要"><input class="description" placeholder="证据说明"></div>').join('');document.querySelector('#createKey').value=crypto.randomUUID();
function createPayload(){return Object.fromEntries(new FormData(document.querySelector('#create')))}async function preflight(){try{const v=await req('/api/cases/preflight',{method:'POST',body:JSON.stringify(createPayload())});show(document.querySelector('#createCheck'),v,v.issues?.length>0);return v}catch(e){err(document.querySelector('#createCheck'),e)}}document.querySelector('#preflightCreate').onclick=preflight;document.querySelector('#create').onsubmit=async e=>{e.preventDefault();const p=await preflight();if(!p?.ready)return;try{current=await req('/api/cases',{method:'POST',body:JSON.stringify(createPayload())});render();show(output,current);loadCases()}catch(x){err(document.querySelector('#createCheck'),x)}};
function revisionPayload(){const f=Object.fromEntries(new FormData(document.querySelector('#revision')));for(const k of ['dot_spacing_mm','dot_height_mm','raised_text_height_mm','bevel_radius_mm','contrast_ratio','mounting_height_mm'])f[k]=Number(f[k]);const old=current?.revisions?.at(-1);f.revision_no=old?old.revision_no+1:1;f.supersedes_revision_id=old?.id||'';f.evidence=[...document.querySelectorAll('.evidence-row')].filter(x=>x.querySelector('.digest').value||x.querySelector('.description').value).map(x=>({kind:x.dataset.kind,digest:x.querySelector('.digest').value,description:x.querySelector('.description').value}));f.remediation_items=[...document.querySelectorAll('[data-finding]:checked')].map(x=>{const text=document.querySelector('[data-explain="'+x.dataset.finding+'"]').value;const parts=text.split('|');return{finding_id:x.dataset.finding,explanation:parts[0]?.trim(),planned_fields:(parts[1]||'').split(',').map(v=>v.trim()).filter(Boolean)}});f.review_responses=[...document.querySelectorAll('[data-return]:checked')].map(x=>{const text=document.querySelector('[data-response="'+x.dataset.return+'"]').value.split('|');return{return_item_id:x.dataset.return,response:text[0]?.trim(),evidence_digest:text[1]?.trim()}});return f}async function previewRev(){if(!current)return;try{revisionPreview=await req('/api/cases/'+current.id+'/revisions/preview',{method:'POST',body:JSON.stringify({expectedVersion:current.version,revision:revisionPayload()})});show(document.querySelector('#revisionPreview'),revisionPreview);return revisionPreview}catch(e){err(document.querySelector('#revisionPreview'),e)}}document.querySelector('#previewRevision').onclick=previewRev;document.querySelector('#revision').onsubmit=async e=>{e.preventDefault();if(!await previewRev())return;try{current=await req('/api/cases/'+current.id+'/revisions',{method:'POST',body:JSON.stringify({expectedVersion:current.version,idempotencyKey:crypto.randomUUID(),revision:revisionPayload()})});render();show(output,current)}catch(x){err(document.querySelector('#revisionPreview'),x)}};
async function mutate(action,payload={}){if(!current)return;const v=await req('/api/cases/'+current.id+'/'+action,{method:'POST',body:JSON.stringify({expectedVersion:current.version,...payload})});if(v?.id===current.id){current=v;render()}return v}document.querySelector('#check').onclick=async()=>{try{show(document.querySelector('#checkResult'),await mutate('check'))}catch(e){err(document.querySelector('#checkResult'),e)}};document.querySelector('#history').onclick=async()=>{try{show(document.querySelector('#checkResult'),await req('/api/cases/'+current.id+'/checks'))}catch(e){err(document.querySelector('#checkResult'),e)}};document.querySelector('#compare').onclick=async()=>{try{const rev=current.revisions.at(-1);show(document.querySelector('#checkResult'),await req('/api/cases/'+current.id+'/compare?revision_id='+encodeURIComponent(rev.id)))}catch(e){err(document.querySelector('#checkResult'),e)}};
document.querySelector('#returnReview').onsubmit=async e=>{e.preventDefault();if(!current)return;const f=Object.fromEntries(new FormData(e.target));const rev=current.revisions.at(-1);try{const items=[{revision_id:rev.id,category:f.category,description:f.description,responsible_role:f.responsible_role}];show(document.querySelector('#reviewResult'),await mutate('review',{reviewerID:f.reviewerID,decision:'RETURN',items}))}catch(x){err(document.querySelector('#reviewResult'),x)}};document.querySelector('#approve').onclick=async()=>{if(!current)return;const ids=(current.return_items||[]).filter(x=>x.status==='RESPONDED').map(x=>x.id);try{show(document.querySelector('#reviewResult'),await mutate('review',{reviewerID:'independent-reviewer',decision:'APPROVE',confirmItemIDs:ids}))}catch(e){err(document.querySelector('#reviewResult'),e)}};
document.querySelector('#previewFreeze').onclick=async()=>{if(!current)return;try{freezePreview=await req('/api/cases/'+current.id+'/freeze-preview');document.querySelector('#freeze').disabled=false;show(document.querySelector('#freezeResult'),freezePreview)}catch(e){err(document.querySelector('#freezeResult'),e)}};document.querySelector('#freeze').onclick=async()=>{if(!freezePreview)return;try{show(document.querySelector('#freezeResult'),await mutate('freeze',{previewDigest:freezePreview.digest}));document.querySelector('#freeze').disabled=true}catch(e){err(document.querySelector('#freezeResult'),e)}};document.querySelector('#issue').onclick=async()=>{try{const cred=await mutate('issue',{issuer:'publisher'});current=await req('/api/cases/'+current.id);render();document.querySelector('#credentialJSON').value=JSON.stringify(cred,null,2);show(document.querySelector('#freezeResult'),cred)}catch(e){err(document.querySelector('#freezeResult'),e)}};
document.querySelector('#useIssued').onclick=()=>{if(current?.credential)document.querySelector('#credentialJSON').value=JSON.stringify(current.credential,null,2)};document.querySelector('#verify').onclick=async()=>{if(!current)return;try{show(document.querySelector('#verifyOut'),await req('/api/cases/'+current.id+'/verify',{method:'POST',body:JSON.stringify({credentialJSON:document.querySelector('#credentialJSON').value})}))}catch(e){err(document.querySelector('#verifyOut'),e)}};document.querySelector('#verifyHistory').onclick=async()=>{if(!current)return;try{show(document.querySelector('#verifyOut'),await req('/api/cases/'+current.id+'/verifications?credential_id='+encodeURIComponent(current.credential?.credential_id||'')))}catch(e){err(document.querySelector('#verifyOut'),e)}};document.querySelector('#refreshCases').onclick=loadCases;document.querySelector('#caseList').onchange=e=>{if(e.target.value)loadCase(e.target.value)};loadStandards().then(loadCases);`
